INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fc7216d26e234f186585a', 'malaysia-airlines', 'Malaysia Airlines', 'Malaysian Airlines | Cricket at 30,000 Feet', '2026-05-15', NULL, 'Ronak Chugh and Atul Kattukaran', 'ronak-chugh', 'https://www.youtube.com/watch?v=xsVsTnNZeVk', 'TVC', 85, 'English', '["Aviation", "Travel", "Sports sponsorship"]', 'product demo', 'A child''s request to play cricket on a flight turns the cabin into a pitch, with the crew''s PA handset used as a commentary mic so each shot lands on a cabin feature', '["warm", "comedic", "celebratory", "family"]', 'Rohit Sharma, Hardik Pandya, Trent Boult', 'complex', '["vfx", "kids", "crowd", "sport", "food", "music_led"]', '[]', '141 million views on the Malaysia Airlines YouTube channel by September 2026; coverage in afaqs, Business Standard, The Tribune, Storyboard18 and The Star', 'A useful reference for a sponsorship activation that has to do more than put a logo on a jersey, and for hiding a product demonstration inside a comedy. The script uses a child asking to play, a public address handset turned into a commentary mic, and seven cabin features scored as cricket beats, so every seat, screen, bed and snack earns its place in the joke. Production shape is a built business class cabin set with authentic uniforms, styled food and a full cast of passengers, three international cricketers available for only a short in season window, aircraft and stadium visual effects, plus a parallel socials unit shooting vertical content. Warm, funny, fan first rather than star first.', 1, 1, 'high', '2026-09-05T16:53:18+00:00');
INSERT OR REPLACE INTO directors (slug, name, bio, credits, strengths, indexed_at) VALUES ('ronak-chugh', 'Ronak Chugh', 'Ronak Chugh is a director working with 1st December Films. He directed the seven-film Google Gemini campaign (2026), which grounds AI in everyday Indian moments from GST filings to passport queues, and the Malaysia Airlines ''Cricket at 30,000 Feet'' film with the Mumbai Indians. His wider body of work spans commercials, music videos and narrative film, including ''The Unfiltered History Tour'' for Vice, among the most awarded campaigns in Indian advertising history, as well as campaigns for Swiggy, Uber and UCB.', '[{"work_id": "6a5fc8e78c1e60255e2a2c23", "slug": "google-gemini-passport-film", "client": "Google Gemini", "campaign": "Google Gemini Passport film", "year": "2026"}, {"work_id": "6a5fc8e78c1e60255e2a2c21", "slug": "google-gemini-gst-film", "client": "Google Gemini", "campaign": "Google Gemini GST film", "year": "2026"}, {"work_id": "6a5fc8e78c1e60255e2a2c1f", "slug": "google-gemini-creator-film", "client": "Google Gemini", "campaign": "Google Gemini Creator film", "year": "2026"}, {"work_id": "6a5fc8e78c1e60255e2a2c1d", "slug": "google-gemini-fd-film", "client": "Google Gemini", "campaign": "Google Gemini FD film", "year": "2026"}, {"work_id": "6a5fc8e78c1e60255e2a2c1b", "slug": "google-gemini-interview-film", "client": "Google Gemini", "campaign": "Google Gemini Interview film", "year": "2026"}, {"work_id": "6a5fc8e78c1e60255e2a2c19", "slug": "google-gemini-galla-film", "client": "Google Gemini", "campaign": "Google Gemini Galla film", "year": "2026"}, {"work_id": "6a5fc8e78c1e60255e2a2c17", "slug": "google-gemini-ac-film", "client": "Google Gemini", "campaign": "Google Gemini AC film", "year": "2026"}, {"work_id": "6a5fc7216d26e234f186585a", "slug": "malaysia-airlines", "client": "Malaysia Airlines", "campaign": "Malaysian Airlines | Cricket at 30,000 Feet", "year": "2026"}, {"work_id": "6a53c3d6d2f5baa54279d39c", "slug": "gemini", "client": "Google Gemini", "campaign": "Google Gemini India films", "year": "2026"}]', 'Best suited to short form product demonstration scripts that have to make a technology feature legible inside an ordinary Indian household or small business, in twenty to thirty seconds. He works from casting-led performance, dressed real interiors, sync sound dialogue and a motion graphics layer carrying the interface beats. Particularly useful on multi-film packages shot together for scale, where tone, palette and edit structure must repeat cleanly across seven films and several language versions.', '2026-09-05T16:53:18+00:00');
